parameters.inputSchema:
{
  "type": "object",
  "required": [
    "responder"
  ],
  "properties": {
    "responder": {
      "type": "boolean",
      "description": "true = contestar; false = silencio"
    },
    "respuesta": {
      "type": "string",
      "description": "texto para el cliente; vacio si responder=false"
    },
    "motivo": {
      "type": "string",
      "description": "por que se decidio contestar o callar"
    }
  }
}
